CREATE TABLE `lectores` (`id_lector` INT NOT NULL AUTO_INCREMENT, `nombre` VARCHAR(110) NOT NULL COMMENT 'Nombre completo', `correo` VARCHAR(160) NOT NULL, `ciudad` VARCHAR(90), `fecha_registro` DATE NOT NULL, `activo` TINYINT(1) NOT NULL DEFAULT 1, PRIMARY KEY (`id_lector`)) ENGINE=InnoDB COMMENT='Personas registradas';
CREATE TABLE `generos` (`id_genero` INT NOT NULL AUTO_INCREMENT, `nombre` VARCHAR(100) NOT NULL, `descripcion` VARCHAR(180), PRIMARY KEY (`id_genero`)) ENGINE=InnoDB COMMENT='Clasificación de recursos';
CREATE TABLE `libros` (`id_libro` INT NOT NULL AUTO_INCREMENT, `id_genero` INT NOT NULL, `nombre` VARCHAR(130) NOT NULL, `precio_reposicion` DECIMAL(11,2) NOT NULL, `ejemplares` INT NOT NULL DEFAULT 0, `activo` TINYINT(1) NOT NULL DEFAULT 1, PRIMARY KEY (`id_libro`), KEY `idx_recurso_categoria` (`id_genero`), CONSTRAINT `fk_recurso_categoria` FOREIGN KEY (`id_genero`) REFERENCES `generos` (`id_genero`)) ENGINE=InnoDB COMMENT='Recursos o artículos del catálogo';
CREATE TABLE `bibliotecas` (`id_biblioteca` INT NOT NULL AUTO_INCREMENT, `nombre` VARCHAR(110) NOT NULL, `ciudad` VARCHAR(90) NOT NULL, `fecha_apertura` DATE, PRIMARY KEY (`id_biblioteca`)) ENGINE=InnoDB COMMENT='Ubicaciones operativas';
CREATE TABLE `bibliotecarios` (`id_bibliotecario` INT NOT NULL AUTO_INCREMENT, `id_biblioteca` INT NOT NULL, `nombre` VARCHAR(110) NOT NULL, `salario` DECIMAL(11,2), `fecha_ingreso` DATE, `activo` TINYINT(1) NOT NULL DEFAULT 1, PRIMARY KEY (`id_bibliotecario`), KEY `idx_empleado_sede` (`id_biblioteca`), CONSTRAINT `fk_empleado_sede` FOREIGN KEY (`id_biblioteca`) REFERENCES `bibliotecas` (`id_biblioteca`)) ENGINE=InnoDB COMMENT='Personal';
CREATE TABLE `prestamos` (`id_prestamo` INT NOT NULL AUTO_INCREMENT, `id_lector` INT NOT NULL, `id_bibliotecario` INT NOT NULL, `id_biblioteca` INT NOT NULL, `fecha` DATE NOT NULL, `estado` VARCHAR(25) NOT NULL, `total` DECIMAL(12,2) NOT NULL, `comentario` VARCHAR(180), PRIMARY KEY (`id_prestamo`), KEY `idx_operacion_persona` (`id_lector`), KEY `idx_operacion_empleado` (`id_bibliotecario`), KEY `idx_operacion_sede` (`id_biblioteca`), CONSTRAINT `fk_operacion_persona` FOREIGN KEY (`id_lector`) REFERENCES `lectores` (`id_lector`), CONSTRAINT `fk_operacion_empleado` FOREIGN KEY (`id_bibliotecario`) REFERENCES `bibliotecarios` (`id_bibliotecario`), CONSTRAINT `fk_operacion_sede` FOREIGN KEY (`id_biblioteca`) REFERENCES `bibliotecas` (`id_biblioteca`)) ENGINE=InnoDB COMMENT='Registro principal de operaciones';
CREATE TABLE `ejemplares_prestados` (`id_ejemplar_prestado` INT NOT NULL AUTO_INCREMENT, `id_prestamo` INT NOT NULL, `id_libro` INT NOT NULL, `cantidad` INT NOT NULL, `precio_unitario` DECIMAL(11,2) NOT NULL, `descuento` DECIMAL(10,2) NOT NULL DEFAULT 0, PRIMARY KEY (`id_ejemplar_prestado`), KEY `idx_detalle_operacion` (`id_prestamo`), KEY `idx_detalle_recurso` (`id_libro`), CONSTRAINT `fk_detalle_operacion` FOREIGN KEY (`id_prestamo`) REFERENCES `prestamos` (`id_prestamo`), CONSTRAINT `fk_detalle_recurso` FOREIGN KEY (`id_libro`) REFERENCES `libros` (`id_libro`)) ENGINE=InnoDB COMMENT='Detalle de recursos por operación';
CREATE TABLE `cobros_prestamo` (`id_cobro_prestamo` INT NOT NULL AUTO_INCREMENT, `id_prestamo` INT NOT NULL, `fecha_pago` DATE NOT NULL, `monto` DECIMAL(12,2) NOT NULL, `metodo` VARCHAR(25) NOT NULL, `confirmado` TINYINT(1) NOT NULL DEFAULT 1, PRIMARY KEY (`id_cobro_prestamo`), KEY `idx_pago_operacion` (`id_prestamo`), CONSTRAINT `fk_pago_operacion` FOREIGN KEY (`id_prestamo`) REFERENCES `prestamos` (`id_prestamo`)) ENGINE=InnoDB COMMENT='Movimientos de cobro';
CREATE TABLE `devoluciones` (`id_devolucion` INT NOT NULL AUTO_INCREMENT, `id_prestamo` INT NOT NULL, `fecha_evento` DATE NOT NULL, `tipo` VARCHAR(50) NOT NULL, `descripcion` VARCHAR(220), `puntuacion` INT, PRIMARY KEY (`id_devolucion`), KEY `idx_evento_operacion` (`id_prestamo`), CONSTRAINT `fk_evento_operacion` FOREIGN KEY (`id_prestamo`) REFERENCES `prestamos` (`id_prestamo`)) ENGINE=InnoDB COMMENT='Eventos de seguimiento asociados a una operación';
